using SoulsFormats;
using System.Text;

internal static class CatacombsPinwheelAudit {
    static string Leaf(string path)=>Path.GetFileName(path.Replace('\\','/'));
    internal static void Run(Func<string,byte[]?> source,MSB1 map,string definitions,Action<string,object> save) {
        var actors=map.Parts.Enemies.Where(p=>p.ModelName=="c3320").ToArray();
        if(actors.Length!=15)throw new InvalidDataException("Pinwheel source population changed");
        save("pinwheel-actors.json",actors.Select(p=>new{p.Name,p.EntityID,p.NPCParamID,p.ThinkParamID,p.InitAnimID,p.Position,p.Rotation,p.CollisionName,p.DrawGroups,p.DispGroups}).ToArray());
        var game=BND3.Read(source("param/GameParam/GameParam.parambnd.dcx")!);
        PARAM Table(string name,string definition){var p=PARAM.Read(game.Files.Single(f=>Leaf(f.Name)==name+".param").Bytes);p.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(definitions,definition+".xml")));return p;}
        var npcs=Table("NpcParam","NpcParam");var thinks=Table("NpcThinkParam","NpcThinkParam");
        save("pinwheel-parameters.json",new{Npcs=npcs.Rows.Where(r=>actors.Any(p=>p.NPCParamID==r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)}),Thinks=thinks.Rows.Where(r=>actors.Any(p=>p.ThinkParamID==r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)})});
        var bank=BND3.Read(source("chr/c3320.anibnd.dcx")!);var tae=TAE.Read(bank.Files.Single(f=>TAE.Is(f.Bytes.ToArray())).Bytes);var model=MapCharacters.Authored(source,"c3320");var flver=FLVER2.Read(model.Model);
        save("pinwheel-character.json",new{Nodes=flver.Nodes.Select(n=>new{n.Name,n.ParentIndex,n.Translation,n.Scale}),Dummies=flver.Dummies.Select(d=>new{d.ReferenceID,d.ParentBoneIndex,d.AttachBoneIndex,d.Position,d.Forward,d.Upward}),Physical=bank.Files.Select(f=>new{f.ID,f.Name}),Actions=tae.Animations.Select(a=>new{a.ID,a.AnimFileName,Events=a.Events.Select(e=>new{e.Type,e.StartTime,e.EndTime,Data=Convert.ToHexString(e.GetParameterBytes(false))})})});
        var events=EMEVD.Read(source("event/m13_00_00_00.emevd.dcx")!);var relevant=events.Events.Where(e=>e.ID==0||e.ID is >=11305390 and <=11305398||e.Instructions.Any(i=>Enumerable.Range(0,i.ArgData.Length/4).Any(n=>actors.Any(p=>p.EntityID==BitConverter.ToInt32(i.ArgData,n*4))))).ToList();
        for(int index=0;index<relevant.Count;index++)if(relevant[index].ID!=0)foreach(var call in relevant[index].Instructions.Where(i=>i.Bank==2000&&i.ID==0&&i.ArgData.Length>=8)){int id=BitConverter.ToInt32(call.ArgData,4);var target=events.Events.SingleOrDefault(e=>e.ID==id);if(target!=null&&relevant.All(e=>e.ID!=id))relevant.Add(target);}
        save("pinwheel-events.json",relevant.Select(e=>new{e.ID,e.RestBehavior,Parameters=e.Parameters.Select(p=>new{p.InstructionIndex,p.TargetStartByte,p.SourceStartByte,p.ByteCount}),Instructions=e.Instructions.Select(i=>new{i.Bank,i.ID,Args=Convert.ToHexString(i.ArgData),Words=Enumerable.Range(0,i.ArgData.Length/4).Select(n=>BitConverter.ToInt32(i.ArgData,n*4))})}).ToArray());
        var common=BND3.Read(source("script/aicommon.luabnd.dcx")!);var area=BND3.Read(source("script/m13_00_00_00.luabnd.dcx")!);var goals=thinks.Rows.Where(r=>actors.Any(p=>p.ThinkParamID==r.ID)).Select(r=>Convert.ToInt32(r["battleGoalID"].Value)).Distinct().ToArray();
        foreach(int goal in goals){string leaf=goal.ToString("D6")+"_battle.lua";var local=area.Files.Where(f=>Leaf(f.Name)==leaf).ToArray();var script=local.Length==1?local[0]:common.Files.Single(f=>Leaf(f.Name)==leaf);var root=Lua50.Read(script.Bytes.ToArray());save("pinwheel-ai-"+goal+".json",new{Goal=goal,Globals=Lua50.Globals(root).Order(),Exports=Lua50.Exports(root).Keys,Numbers=Lua50.All(root).SelectMany(f=>f.Constants).OfType<double>().Distinct().Order(),Strings=Lua50.All(root).SelectMany(f=>f.Constants).OfType<byte[]>().Where(b=>b.All(c=>c<128)).Select(Encoding.ASCII.GetString).Distinct().Order()});}
        save("pinwheel-regions.json",map.Regions.GetEntries().Where(r=>r.EntityID==1302500||r.EntityID is >=1302600 and <=1302612||r.EntityID is >=1302996 and <=1302999).Select(r=>new{r.Name,r.EntityID,r.Position,r.Rotation,Shape=r.Shape.GetType().Name}).ToArray());
        var effects=Table("SpEffectParam","SpEffect");var effectIds=npcs.Rows.Where(r=>actors.Any(p=>p.NPCParamID==r.ID)).SelectMany(r=>Enumerable.Range(0,8).Select(n=>Convert.ToInt32(r["spEffectID"+n].Value)).Append(Convert.ToInt32(r["GameClearSpEffectID"].Value))).Concat(tae.Animations.SelectMany(a=>a.Events).Where(e=>e.Type is 66 or 67).Select(e=>BitConverter.ToInt32(e.GetParameterBytes(false)))).Where(id=>id>0).ToHashSet();save("pinwheel-effects.json",effects.Rows.Where(r=>effectIds.Contains((int)r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)}).ToArray());
        int[] variations=npcs.Rows.Where(r=>actors.Any(p=>p.NPCParamID==r.ID)).Select(r=>Convert.ToInt32(r["behaviorVariationId"].Value)).Distinct().ToArray();var behavior=Table("BehaviorParam","BehaviorParam");var rows=behavior.Rows.Where(r=>variations.Contains(Convert.ToInt32(r["variationId"].Value))).ToArray();var bullet=Table("Bullet","BulletParam");var attacks=Table("AtkParam_Npc","AtkParam");var bullets=rows.Where(r=>Convert.ToInt32(r["refType"].Value)==1).Select(r=>Convert.ToInt32(r["refId"].Value)).ToHashSet();var damage=rows.Where(r=>Convert.ToInt32(r["refType"].Value)==0).Select(r=>Convert.ToInt32(r["refId"].Value)).Concat(bullet.Rows.Where(r=>bullets.Contains((int)r.ID)).Select(r=>Convert.ToInt32(r["atkId_Bullet"].Value))).ToHashSet();
        save("pinwheel-combat.json",new{Behavior=rows.Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)}),Bullet=bullet.Rows.Where(r=>bullets.Contains((int)r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)}),Attack=attacks.Rows.Where(r=>damage.Contains((int)r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>c.Value)})});
        Console.WriteLine("AUDIT Pinwheel source15actors,"+goals.Length+" distinct AI goals,"+relevant.Count+" encounter/dependency events; no boss adapter or helpers enabled");
    }
}
